package com.rewang.app;
import android.content.Context;import android.graphics.*;import android.view.View;import org.json.*;import java.util.*;
/** Native Canvas, clips the series at the replay cursor. */
public final class MarketChart extends View {
 private final JSONArray bars;private final String end;private final Paint pen=new Paint(3);private float density;
 public MarketChart(Context c,JSONArray a,String date){super(c);bars=a;end=date;density=getResources().getDisplayMetrics().density;setContentDescription("未复权收盘价走势图，截至 "+date);}
 protected void onDraw(Canvas canvas){super.onDraw(canvas);List<JSONObject> points=new ArrayList<>();double lo=Double.MAX_VALUE,hi=-Double.MAX_VALUE;for(int i=0;bars!=null&&i<bars.length();i++){JSONObject b=bars.optJSONObject(i);if(b.optString("date").compareTo(end)>0)continue;double v=b.optDouble("close");if(!Double.isFinite(v))continue;points.add(b);lo=Math.min(lo,v);hi=Math.max(hi,v);}if(points.isEmpty())return;double spread=Math.max(hi-lo,1);lo-=spread*.12;hi+=spread*.12;float w=getWidth(),h=getHeight(),left=44*density,right=w-8*density,top=22*density,bottom=h-30*density;pen.setTextSize(9*density);for(int k=0;k<3;k++){float y=top+(bottom-top)*k/2;pen.setColor(0xffe1dbd0);pen.setStrokeWidth(density*.6f);canvas.drawLine(left,y,right,y,pen);pen.setColor(0xff8b9697);canvas.drawText(String.format(Locale.US,"%.0f",hi-(hi-lo)*k/2),0,y+3*density,pen);}Path path=new Path();for(int i=0;i<points.size();i++){float x=left+(right-left)*i/Math.max(1,points.size()-1),y=(float)(bottom-(points.get(i).optDouble("close")-lo)/(hi-lo)*(bottom-top));if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}pen.setColor(0xffa66a4e);pen.setStyle(Paint.Style.STROKE);pen.setStrokeWidth(2*density);canvas.drawPath(path,pen);pen.setStyle(Paint.Style.FILL);pen.setColor(0xff8b9697);canvas.drawText(points.get(0).optString("date").substring(5),left,h-7*density,pen);canvas.drawText(points.get(points.size()-1).optString("date").substring(5),right-34*density,h-7*density,pen);}
}
